package com.meetspace.repository;
import com.meetspace.dto.AdminDtos.*; import java.time.*; import java.util.*; import org.springframework.jdbc.core.JdbcTemplate; import org.springframework.stereotype.Repository;
@Repository public class AdminRepository { private final JdbcTemplate jdbc; public AdminRepository(JdbcTemplate jdbc){this.jdbc=jdbc;} public Dashboard dashboard(){return jdbc.queryForObject("select (select count(*) from employees),(select count(*) from employees e join users u on u.id=e.user_id where u.is_active),(select count(*) from rooms where is_active),(select count(*) from bookings where booking_date=current_date),(select count(*) from bookings where booking_date>=current_date and status in ('PENDING','CONFIRMED')),(select count(*) from bookings where status='CANCELLED')",(r,n)->new Dashboard(r.getLong(1),r.getLong(2),r.getLong(3),r.getLong(4),r.getLong(5),r.getLong(6)));} public List<Employee> employees(){return jdbc.query("select e.id,e.employee_code,e.first_name,e.last_name,u.email,e.department,e.phone,u.is_active,u.email_verified,e.created_at from employees e join users u on u.id=e.user_id order by e.created_at desc",(r,n)->new Employee(UUID.fromString(r.getString(1)),r.getString(2),r.getString(3),r.getString(4),r.getString(5),r.getString(6),r.getString(7),r.getBoolean(8),r.getBoolean(9),r.getTimestamp(10).toInstant()));} public List<Booking> bookings(){return jdbc.query("select b.id,e.first_name,e.last_name,u.email,r.name,r.room_code,b.booking_date,b.start_time,b.end_time,b.purpose,b.status,b.created_at from bookings b join employees e on e.id=b.employee_id join users u on u.id=e.user_id join rooms r on r.id=b.room_id order by b.booking_date desc,b.start_time desc",(x,n)->new Booking(UUID.fromString(x.getString(1)),x.getString(2)+" "+x.getString(3),x.getString(4),x.getString(5),x.getString(6),x.getObject(7,LocalDate.class),x.getObject(8,LocalTime.class),x.getObject(9,LocalTime.class),x.getString(10),x.getString(11),x.getTimestamp(12).toInstant()));} }
